SELECT p.gender, a.admittime, a.dischtime, a.los, d.diagnosis_code, COUNT(DISTINCT p.subject_id) AS patient_count, AVG(d.diagnosis_code) AS avg_diagnosis_code FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 48 AND a.admittime BETWEEN '2015-01-01' AND '2020-12-31' AND d.diagnosis_code IN ('4010001', '4010002') AND (a.dischtime - a.admittime) BETWEEN 1 AND 7 AND (a.dischtime - a.admittime) BETWEEN 5 AND 7 GROUP BY p.gender, a.admittime, a.dischtime, a.los, d.diagnosis_code ORDER BY p.gender, a.admittime, a.dischtime, a.los, d.diagnosis_code NULLS LAST;